	"action" text NOT NULL,
	"old_valid_from" timestamp with time zone,
	"old_valid_to" timestamp with time zone,
	"new_valid_from" timestamp with time zone,
	"new_valid_to" timestamp with time zone,
	"changed_at" timestamp with time zone NOT NULL
);--> statement-breakpoint
CREATE INDEX "asset_product_code_change_region_idx" ON "master_data"."asset_product_code_change" ("region");--> statement-breakpoint
CREATE VIEW "master_data"."asset_tag_address_history" AS (select "master_data"."asset_tags"."id" as "asset_tag_id", "master_data"."asset_tags"."region", "master_data"."asset_tags"."asset_id", "master_data"."asset_placement"."id" as "placement_id", "master_data"."asset_tags"."tag_name", "master_data"."asset_tags"."tag_role", "master_data"."asset_tags"."data_source_id", "master_data"."work_unit"."id" as "work_unit_id", "master_data"."work_center"."id" as "work_center_id", "master_data"."area"."id" as "area_id", "master_data"."site"."id" as "site_id", "master_data"."enterprise"."id" as "enterprise_id", case
          when "master_data"."data_source"."node_naming" = 'manual' then nullif("master_data"."asset_tags"."node", '')
          when "master_data"."data_source"."node_naming" = 'generated' and "master_data"."data_source"."protocol" = 'opcua' and (case when "master_data"."enterprise"."id" is not null and "master_data"."asset"."asset_tag" <> '' and "master_data"."asset_tags"."tag_name" <> '' then regexp_replace("master_data"."enterprise"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."site"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."area"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_center"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_unit"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."asset"."asset_tag", '[^A-Za-z0-9_]', '_', 'g') || '/' || "master_data"."asset_tags"."tag_name" end) is not null
            then 'nsu=' || "master_data"."data_source"."namespace_uri" || ';s=' || (case when "master_data"."enterprise"."id" is not null and "master_data"."asset"."asset_tag" <> '' and "master_data"."asset_tags"."tag_name" <> '' then regexp_replace("master_data"."enterprise"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."site"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."area"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_center"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_unit"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."asset"."asset_tag", '[^A-Za-z0-9_]', '_', 'g') || '/' || "master_data"."asset_tags"."tag_name" end)
          when "master_data"."data_source"."node_naming" = 'generated' and "master_data"."data_source"."protocol" = 'mqtt' and (case when "master_data"."enterprise"."id" is not null and "master_data"."asset"."asset_tag" <> '' and "master_data"."asset_tags"."tag_name" <> '' then regexp_replace("master_data"."enterprise"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."site"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."area"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_center"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_unit"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."asset"."asset_tag", '[^A-Za-z0-9_]', '_', 'g') || '/' || "master_data"."asset_tags"."tag_name" end) is not null
            then case when "master_data"."data_source"."topic_root" = '' then '' else "master_data"."data_source"."topic_root" || '/' end || (case when "master_data"."enterprise"."id" is not null and "master_data"."asset"."asset_tag" <> '' and "master_data"."asset_tags"."tag_name" <> '' then regexp_replace("master_data"."enterprise"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."site"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."area"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_center"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_unit"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."asset"."asset_tag", '[^A-Za-z0-9_]', '_', 'g') || '/' || "master_data"."asset_tags"."tag_name" end)
        end as "node", greatest("master_data"."asset_tags"."valid_from", "master_data"."asset_placement"."valid_from") as "valid_from", least("master_data"."asset_tags"."valid_to", "master_data"."asset_placement"."valid_to") as "valid_to" from "master_data"."asset_tags" inner join "master_data"."asset_placement" on (("master_data"."asset_placement"."region" = "master_data"."asset_tags"."region") and ("master_data"."asset_placement"."asset_id" = "master_data"."asset_tags"."asset_id") and (((("master_data"."asset_tags"."work_unit_id" is null)) or ("master_data"."asset_tags"."work_unit_id" = '') or ("master_data"."asset_placement"."work_unit_id" = "master_data"."asset_tags"."work_unit_id"))) and (((("master_data"."asset_tags"."valid_to" is null)) or ("master_data"."asset_placement"."valid_from" < "master_data"."asset_tags"."valid_to"))) and (((("master_data"."asset_placement"."valid_to" is null)) or ("master_data"."asset_tags"."valid_from" < "master_data"."asset_placement"."valid_to")))) left join "master_data"."data_source" on (("master_data"."data_source"."id" = "master_data"."asset_tags"."data_source_id") and ("master_data"."data_source"."region" = "master_data"."asset_tags"."region")) left join "master_data"."asset" on (("master_data"."asset"."id" = "master_data"."asset_tags"."asset_id") and ("master_data"."asset"."region" = "master_data"."asset_tags"."region")) left join "master_data"."work_unit" on (("master_data"."work_unit"."id" = "master_data"."asset_placement"."work_unit_id") and ("master_data"."work_unit"."region" = "master_data"."asset_tags"."region")) left join "master_data"."work_center" on (("master_data"."work_center"."id" = "master_data"."work_unit"."work_center_id") and ("master_data"."work_center"."region" = "master_data"."asset_tags"."region")) left join "master_data"."area" on (("master_data"."area"."id" = "master_data"."work_center"."area_id") and ("master_data"."area"."region" = "master_data"."asset_tags"."region")) left join "master_data"."site" on (("master_data"."site"."id" = "master_data"."area"."site_id") and ("master_data"."site"."region" = "master_data"."asset_tags"."region")) left join "master_data"."enterprise" on (("master_data"."enterprise"."id" = "master_data"."site"."enterprise_id") and ("master_data"."enterprise"."region" = "master_data"."asset_tags"."region")));--> statement-breakpoint
CREATE VIEW "master_data"."product_code_mapping_change" AS (select "change_id", "region", "action", "asset_product_code_id", "work_unit_id", "raw_value" as "raw_code", "old_valid_from", "old_valid_to", "new_valid_from", "new_valid_to", "changed_at" as "saved_at" from "master_data"."asset_product_code_change");
